use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

use crate::shared::{
    ids::{BackupCodeId, UserId},
    policies::Ownable,
};

/// A single-use TOTP 2FA recovery code.
///
/// Ten of these are generated by `ConfirmTotpSetupUseCase` when a user
/// finishes enrolling in TOTP 2FA (see the task's SECURITY REQUIREMENTS).
/// The raw code is shown to the user exactly once, at generation time —
/// only its Argon2id hash (`code_hash`, produced via
/// `application::ports::PasswordHasher`, the SAME hasher used for account
/// passwords) is ever persisted, mirroring how `ApiKey.hashed_key` never
/// stores the raw secret either.
///
/// A code is single-use: `mark_used` records `used_at` the moment it is
/// redeemed by `VerifyTotpAndLoginUseCase`, and every lookup path must
/// treat a code with `used_at.is_some()` as no longer valid.
#[derive(Clone, Serialize, Deserialize)]
pub struct BackupCode {
    pub id: BackupCodeId,
    pub user_id: UserId,
    pub code_hash: String,
    pub used_at: Option<DateTime<Utc>>,
    pub created_at: DateTime<Utc>,
}

impl BackupCode {
    pub fn new(
        id: BackupCodeId,
        user_id: UserId,
        code_hash: String,
        created_at: DateTime<Utc>,
    ) -> Self {
        Self {
            id,
            user_id,
            code_hash,
            used_at: None,
            created_at,
        }
    }

    pub fn is_used(&self) -> bool {
        self.used_at.is_some()
    }

    /// Marks this code as redeemed. Callers must also persist the change
    /// via `BackupCodeRepository::mark_used` — this only updates the
    /// in-memory aggregate.
    pub fn mark_used(&mut self, when: DateTime<Utc>) {
        self.used_at = Some(when);
    }
}

impl Ownable for BackupCode {
    fn owner_id(&self) -> UserId {
        self.user_id
    }
}

// The `Debug` impls in this file sit after `mod tests` because they are
// the credential-redaction boundary added and were kept at the
// bottom to keep that PART's diff focused on the impls themselves. The
// ordering is a style preference; the lint is suppressed explicitly here
// rather than reorganising the file, so the diff stays minimal and the
// redaction review remains easy to re-audit.
#[allow(clippy::items_after_test_module)]
#[cfg(test)]
mod tests {
    use super::*;
    use uuid::Uuid;

    #[test]
    fn new_backup_code_starts_unused() {
        let code = BackupCode::new(
            BackupCodeId(Uuid::new_v4()),
            UserId(Uuid::new_v4()),
            "argon2-hash".to_string(),
            Utc::now(),
        );

        assert!(!code.is_used());
        assert!(code.used_at.is_none());
    }

    #[test]
    fn mark_used_sets_used_at() {
        let mut code = BackupCode::new(
            BackupCodeId(Uuid::new_v4()),
            UserId(Uuid::new_v4()),
            "argon2-hash".to_string(),
            Utc::now(),
        );
        let when = Utc::now();

        code.mark_used(when);

        assert!(code.is_used());
        assert_eq!(code.used_at, Some(when));
    }
}

/// Manual Debug that redacts `code_hash`.
impl std::fmt::Debug for BackupCode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("BackupCode")
            .field("id", &self.id)
            .field("user_id", &self.user_id)
            .field("used_at", &self.used_at)
            .field("created_at", &self.created_at)
            .field("code_hash", &"[REDACTED]")
            .finish()
    }
}
